// Static game data tables. The definitions live in data_tables.cpp, which is
// generated by tools/gen_data.py from the OpenHome repository.
#pragma once

namespace ohnx {

// Name tables. Index == game ID. Index 0 is a placeholder.
extern const char* const kSpeciesNames[];  // index = National Dex number (0 = "Egg")
extern const unsigned kSpeciesNamesCount;  // 1026
extern const char* const kMoveNames[];
extern const unsigned kMoveNamesCount;
extern const char* const kAbilityNames[];
extern const unsigned kAbilityNamesCount;
extern const char* const kItemNames[];
extern const unsigned kItemNamesCount;

// Experience growth curve per National Dex number.
// 0 Erratic, 1 Fast, 2 MediumFast, 3 MediumSlow, 4 Slow, 5 Fluctuating
extern const unsigned char kGrowth[];
extern const unsigned kGrowthCount;

// Gen 3 internal species index -> National Dex (0 = invalid/filler).
extern const unsigned short kGen3ToNational[];
extern const unsigned kGen3ToNationalCount;

// Scarlet/Violet & Legends Z-A species index -> National Dex.
extern const unsigned short kSvToNational[];
extern const unsigned kSvToNationalCount;

// Gen 3 character sets (byte -> UTF-16 code unit, 0xFFFF = invalid).
extern const char16_t kGen3IntChars[];
extern const unsigned kGen3IntCharsCount;
extern const char16_t kGen3JpnChars[];
extern const unsigned kGen3JpnCharsCount;

// Gen 4 character set, sorted by `code`.
struct Gen4Pair {
    unsigned short code;
    unsigned short utf16;
};
extern const Gen4Pair kGen4Chars[];
extern const unsigned kGen4CharsCount;

}  // namespace ohnx
